// Session management: create, update, query
const data = items[0].json;
const action = data.action || 'get';

if (action === 'create') {
  const sessionId = data.session_id || ('sess_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
  return [{
    json: {
      session_id: sessionId,
      origin: data.origin || null,
      destination: data.destination || null,
      current_location: data.current_location || null,
      heading_deg: data.heading_deg || null,
      route: data.route || null,
      status: 'active',
      last_perception: null,
      last_decision: null,
      last_voice_instruction: null,
      created_at: Date.now(),
      updated_at: Date.now(),
    }
  }];
}

if (action === 'update') {
  // In production, this would read/write from a database.
  // For n8n Cloud, use the n8n Memory or an external DB.
  return [{
    json: {
      session_id: data.session_id,
      updated_fields: Object.keys(data).filter(k => k !== 'action' && k !== 'session_id'),
      updated_at: Date.now(),
      note: 'In production, persist to database. n8n Memory or Redis recommended.',
    }
  }];
}

if (action === 'get') {
  return [{
    json: {
      session_id: data.session_id,
      note: 'In production, fetch from database. This demo returns placeholder.',
      status: 'active',
    }
  }];
}

return [{ json: { error: 'Unknown action: ' + action, status: 'error' } }];
